static void rejected(u32 location,u32 offset,u32 requested) {
    u32 ea=0xdeadbeefu,bytes=0x12345678u;
    assert(cellGcmNativeReadLocatedRange(location,offset,requested,&ea,&bytes)!=CELL_OK);
    assert(ea==0xdeadbeefu&&bytes==0x12345678u);
}
