    assert(cellGcmNativeReadLocatedRange(0,0xff0,16,&ea,&bytes)==CELL_OK);
    assert(ea==0x06000ff0&&bytes==16);
    rejected(0,0xff0,17);rejected(0,0x1000,1);rejected(0,0,0);
    s_config.localAddress=0xfffffff0u;s_config.localSize=0x1000;
    rejected(0,8,16);rejected(0,0xfffffff8u,16);rejected(2,0,16);
    s_ea_address_table[0]=3;s_ea_address_table[1]=9;
    assert(cellGcmNativeReadLocatedRange(1,0xffff8,16,&ea,&bytes)==CELL_OK);
    assert(ea==0x3ffff8&&bytes==8);
    assert(cellGcmNativeReadLocatedRange(1,0x100000,8,&ea,&bytes)==CELL_OK);
    assert(ea==0x900000&&bytes==8);
    s_ea_address_table[1]=0xffff;rejected(1,0x100000,8);
    s_ea_address_table[1]=0x1000;rejected(1,0x100000,8); // beyond4GiB EA
    s_ea_address_table[1]=0;rejected(1,0x100000,8); // guestzero unavailable
    ppu_vm_size=0x300000;rejected(1,0xffff8,16);ppu_vm_size=0;
    assert(cellGcmNativeReadLocatedRange(1,0xffff8,16,NULL,&bytes)!=CELL_OK);
    assert(cellGcmNativeReadLocatedRange(1,0xffff8,16,&ea,NULL)!=CELL_OK);
    assert(cellGcmNativeReadLocatedRange(1,0xffff8,16,&ea,&ea)!=CELL_OK);
